function demoPayEnabled(env) {
  return env.ALLOW_DEMO_PAY === '1' || env.ALLOW_DEMO_PAY === 'true';
}
function normalizeProof(proof) {
  const p = String(proof || '').trim();
  if (p.length < 8 || p.length > 200) return null;
  if (/^(test|demo|credit-pay|null|undefined|0|tx)$/i.test(p)) return null;
  return p;
}
async function occupyTxProof(env, proof, invoiceId) {
  const hash = await sha('wep3-tx|' + proof);
  const key = 'wep3:txproof:' + hash;
  const existing = await get(env, key, null);
  if (existing) {
    if (existing.invoice_id === invoiceId) return {ok: true, idempotent: true, hash};
    return {error: 'proof_replay', status: 409, proof_hash: hash};
  }
  await put(env, key, {invoice_id: invoiceId, hash, at: new Date().toISOString()});
  return {ok: true, idempotent: false, hash};
}
async function fulfillModel(env, skill, title, extra) {
  const url = env.MODEL_GATEWAY_URL;
  if (!url) return {error: 'model_gateway_unconfigured', status: 503};
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), 15000);
  try {
    const headers = {'content-type': 'application/json'};
    if (env.MODEL_GATEWAY_TOKEN) headers.authorization = 'Bearer ' + env.MODEL_GATEWAY_TOKEN;
    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({agent: skill.owner, skill: skill.id, title, product: skill.product, extra: extra || null}),
      signal: ac.signal
    });
    if (!res.ok) return {error: 'model_gateway_http', status: 502};
    const data = await res.json().catch(() => ({}));
    const text = String(data.deliverable || data.text || '').trim();
    if (text.length < 8 || !text.includes('ltzzz.com')) return {error: 'model_deliverable_invalid', status: 422};
    return {text, model: data.model || skill.owner};
  } catch (err) {
    return {error: 'model_gateway_failed', message: String(err && err.message || err), status: 503};
  } finally {
    clearTimeout(timer);
  }
}
